// conformance.cpp — pins the C++ port to src/orb.js through the vectors generated by
// native/conformance/generate.mjs, and proves the HLSL compiles (and, when a D3D11
// device is available, renders a frame with plausible coverage). SPEC.md §7.

#include "orb/orb.h"
#include "conformance_vectors.h"

#include <algorithm>
#include <cmath>
#include <cstdio>
#include <cstring>
#include <stdexcept>
#include <string>
#include <vector>

